 26→// Droid implements the Agent interface for Factory AI Droid.
 27→type Droid struct{}
 28→
 29→func (d *Droid) Name() string               { return "factoryai-droid" }
 30→func (d *Droid) Binary() string             { return "droid" }
 31→func (d *Droid) EntireAgent() string        { return "factoryai-droid" }
 32→func (d *Droid) PromptPattern() string      { return `>` }
 33→func (d *Droid) TimeoutMultiplier() float64 { return 1.5 }
