 34→// HookNames returns the hook verbs Factory AI Droid supports.
 35→// These become subcommands: entire hooks factoryai-droid <verb>
 36→func (f *FactoryAIDroidAgent) HookNames() []string {
 37→	return []string{
 38→		HookNameSessionStart,
 39→		HookNameSessionEnd,
 40→		HookNameStop,
 41→		HookNameUserPromptSubmit,
 42→		HookNamePreToolUse,
 43→		HookNamePostToolUse,
 44→		HookNameSubagentStop,
 45→		HookNamePreCompact,
 46→		HookNameNotification,
 47→	}
 48→}
