 76→// --- TranscriptAnalyzer ---
 77→
 78→// GetTranscriptPosition returns the current line count of the JSONL transcript.
 79→func (f *FactoryAIDroidAgent) GetTranscriptPosition(path string) (int, error) {
 80→	_, pos, err := ParseDroidTranscript(path, 0)
 81→	if err != nil {
 82→		return 0, err
 83→	}
 84→	return pos, nil
 85→}
 86→
 87→// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
 88→func (f *FactoryAIDroidAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
 89→	lines, currentPos, err := ParseDroidTranscript(path, startOffset)
 90→	if err != nil {
 91→		return nil, 0, fmt.Errorf("failed to parse transcript: %w", err)
 92→	}
 93→	files := ExtractModifiedFiles(lines)
 94→	return files, currentPos, nil
 95→}
 96→
 97→// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
 98→func (f *FactoryAIDroidAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 99→	lines, _, err := ParseDroidTranscript(sessionRef, fromOffset)
100→	if err != nil {
101→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
102→	}
103→
104→	var prompts []string
105→	for i := range lines {
106→		if lines[i].Type != transcript.TypeUser {
107→			continue
108→		}
109→		content := transcript.ExtractUserContent(lines[i].Message)
110→		if content != "" {
111→			prompts = append(prompts, textutil.StripIDEContextTags(content))
112→		}
113→	}
114→	return prompts, nil
115→}
116→
117→// ExtractSummary extracts the last assistant message as a session summary.
118→func (f *FactoryAIDroidAgent) ExtractSummary(sessionRef string) (string, error) {
119→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
120→	if err != nil {
121→		return "", fmt.Errorf("failed to read transcript: %w", err)
122→	}
123→	lines, _, err := ParseDroidTranscriptFromBytes(data, 0)
124→	if err != nil {
125→		return "", fmt.Errorf("failed to parse transcript: %w", err)
126→	}
127→
128→	for i := len(lines) - 1; i >= 0; i-- {
129→		if lines[i].Type != transcript.TypeAssistant {
130→			continue
131→		}
132→		var msg transcript.AssistantMessage
133→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
134→			continue
135→		}
136→		for _, block := range msg.Content {
137→			if block.Type == transcript.ContentTypeText && block.Text != "" {
138→				return block.Text, nil
139→			}
140→		}
141→	}
142→	return "", nil
143→}
