194→func (f *FactoryAIDroidAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
195→	raw, err := agent.ReadAndParseHookInput[stopRaw](stdin)
196→	if err != nil {
197→		return nil, err
198→	}
199→
200→	model := raw.Model
201→	// If model not provided in hook payload, extract from transcript
202→	if model == "" && raw.TranscriptPath != "" {
203→		model = ExtractModelFromTranscript(raw.TranscriptPath)
204→	}
205→
206→	return &agent.Event{
207→		Type:       agent.TurnEnd,
208→		SessionID:  raw.SessionID,
209→		SessionRef: raw.TranscriptPath,
210→		Model:      model,
211→		Timestamp:  time.Now(),
212→	}, nil
213→}
