115→// ReadSession reads a session from Factory AI Droid's storage (JSONL transcript file).
116→// The session data is stored in NativeData as raw JSONL bytes.
117→// ModifiedFiles is computed by parsing the transcript.
118→func (f *FactoryAIDroidAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
119→	if input.SessionRef == "" {
120→		return nil, errors.New("session reference (transcript path) is required")
121→	}
122→
123→	data, err := os.ReadFile(input.SessionRef)
124→	if err != nil {
125→		return nil, fmt.Errorf("failed to read transcript: %w", err)
126→	}
127→
128→	lines, _, err := ParseDroidTranscriptFromBytes(data, 0)
129→	if err != nil {
130→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
131→	}
132→
133→	return &agent.AgentSession{
134→		SessionID:     input.SessionID,
135→		AgentName:     f.Name(),
136→		SessionRef:    input.SessionRef,
137→		StartTime:     time.Now(),
138→		NativeData:    data,
139→		ModifiedFiles: ExtractModifiedFiles(lines),
140→	}, nil
141→}
