150→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
151→	cfg := &runConfig{}
152→	for _, o := range opts {
153→		o(cfg)
154→	}
155→
156→	// Model is configured via sessionDefaultSettings in ~/.factory/settings.json.
157→	args := []string{"exec", "--skip-permissions-unsafe", prompt}
158→	displayArgs := []string{"exec", "--skip-permissions-unsafe", fmt.Sprintf("%q", prompt)}
159→
160→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
161→	cmd.Dir = dir
162→	cmd.Stdin = nil
163→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
164→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
165→	cmd.Cancel = func() error {
166→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
167→	}
168→	cmd.WaitDelay = 5 * time.Second
169→
170→	var stdout, stderr strings.Builder
171→	cmd.Stdout = &stdout
172→	cmd.Stderr = &stderr
173→
174→	err := cmd.Run()
175→	exitCode := 0
176→	if err != nil {
177→		exitErr := &exec.ExitError{}
178→		if errors.As(err, &exitErr) {
179→			exitCode = exitErr.ExitCode()
180→		} else {
181→			exitCode = -1
182→		}
183→	}
184→
185→	return Output{
186→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
187→		Stdout:   stdout.String(),
188→		Stderr:   stderr.String(),
189→		ExitCode: exitCode,
190→	}, err
191→}
