193→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
194→	name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
195→	// Model is configured via sessionDefaultSettings in ~/.factory/settings.json.
196→	// Interactive mode doesn't support --model or --skip-permissions-unsafe (exec-only flags).
197→	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, d.Binary())
198→	if err != nil {
199→		return nil, err
200→	}
201→
202→	// Wait for the interactive prompt indicator.
203→	if _, err := s.WaitFor(`>`, 30*time.Second); err != nil {
204→		_ = s.Close()
205→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
206→	}
207→	s.stableAtSend = ""
208→
209→	return s, nil
210→}
